// TDZ demo
console.log(a); // undefined (var hoisted+initialised)
console.log(b); // ReferenceError (let in TDZ)
var a = 1;
let b = 2;

// const mutation
const arr = [1,2,3];
arr.push(4);   // OK — array is mutated, not reassigned
arr = [];      // TypeError — reassignment blocked

// var — all closures share the same i:
const fns1 = [];
for (var i = 0; i < 3; i++) { fns1.push(() => i); }
fns1[0](); // 3 (final value)

// let — each iteration has its own binding:
const fns2 = [];
for (let i = 0; i < 3; i++) { fns2.push(() => i); }
fns2[0](); // 0
fns2[1](); // 1
fns2[2](); // 2

var fns = [];
for (var i = 0; i < 3; i++) {
  fns.push(() => i);
}
console.log(fns[0](), fns[1](), fns[2]());

var fns = [];
for (let i = 0; i < 3; i++) {
  fns.push(() => i);
}
console.log(fns[0](), fns[1](), fns[2]());
